func:
// Dieser Node ist nur die Bruecke zwischen dem sichtbaren Flow und dem getesteten JS-Kern.
// Node-RED stellt dafuer vier Objekte bereit:
// - msg enthaelt das aktuelle Ereignis und seine Nutzdaten.
// - global enthaelt die in settings.js geladenen Module und Konfigurationen.
// - context speichert den fluechtigen Zustand genau dieses Function-Nodes.
// - env liest Laufzeiteinstellungen aus den Umgebungsvariablen.

// 1. Fachmodul, MQTT-Topics und Idle-Seed-Vorlagen aus dem globalen Kontext laden.
const api = global.get('aiCpsOrchestration');
const topics = global.get('aiCpsTopics');
const idleSeeds = global.get('aiCpsIdleSeedTemplates');

// 2. Bereits vorhandene Runtime laden. Sie enthaelt unter anderem Rolling Windows,
// offene Requests und den Fault-Latch und wird nicht dauerhaft gespeichert.
let runtime = context.get('runtime');

// 3. Nur fuer die erste Nachricht nach Start oder Deploy eine neue Runtime anlegen.
if (!runtime) {
    const enabled = String(env.get('COMMAND_OUTPUT_ENABLED') || 'false').toLowerCase() === 'true';
    runtime = api.createRuntime({ topics, idleSeedTemplates: idleSeeds, commandOutputEnabled: enabled });
    context.set('runtime', runtime);
}

// 4. Genau ein zuvor von einem change-Node klassifiziertes Ereignis verarbeiten.
// _ai_domain ist nur bei modellbezogenen Ereignissen storage, vgr oder hbw.
const actions = runtime.handleEvent(msg._ai_event, msg.payload, msg._ai_domain || null);

// 5. Den aktualisierten Zustand fuer die naechste Nachricht im Node-Context ablegen.
context.set('runtime', runtime);

// Ohne Aktion darf die Nachricht den Function-Node nicht verlassen.
if (actions.length === 0) return null;

// Die nachfolgenden split-/switch-Nodes verteilen diese Aktionsliste sichtbar.
msg.payload = actions;
return msg;

// Dieser Node aktualisiert nur den konsistenten Reportzustand. Core-Nodes schreiben die Dateien.
// global liefert das in settings.js geladene Reportingmodul.
const reporting = global.get('aiCpsReporting');

// context behaelt Zaehler, Trefferzahlen und die Run-ID fuer den aktuellen Lauf.
let state = context.get('reportState');

// Ein Fabrikstatus darf nur einen bereits begonnenen und passend korrelierten Lauf abschliessen.
if (msg._report_event === 'factory_status') {
  if (!state) return null;
  const finalized = reporting.finalizeRun(state, msg.payload);
  if (!finalized) return null;
  context.set('reportState', null);
  msg.payload = finalized.files;
  return msg;
}

// Beim ersten abgeschlossenen KI-Zyklus einen neuen Reportlauf unter REPORT_ROOT anlegen.
if (!state) state = reporting.createReportState(env.get('REPORT_ROOT') || '/reports/orchestration_simulation');

// Aus demselben Zyklusergebnis gemeinsam Event, CSV-Zeile und laufende Run-Summary bilden.
const recorded = reporting.recordCycle(state, msg.payload);
context.set('reportState', recorded.state);

// Die nachfolgenden split-/switch-/file-Nodes verteilen und schreiben die Dateien.
msg.payload = recorded.files;
return msg;

// Dieser Node ist nur die Bruecke zum getesteten virtuellen Fabrikzustandskern.
// global enthaelt Modul, Topics und alle versionierten Payload-Traces.
const api = global.get('aiCpsVirtualFactory');
const topics = global.get('aiCpsTopics');

// context speichert den fluechtigen Semaphorzustand genau dieses Function-Nodes.
let factory = context.get('factory');

// Beim ersten Ereignis nach Start oder Deploy die virtuelle Fabrik initialisieren.
// Der vorherige change-Node ordnet die vier Environment-Basiszeiten den Modulen zu.
// FACTORY_SEED macht die Variation jeder Basiszeit um -50 bis +50 Prozent reproduzierbar.
if (!factory) {
    factory = new api.VirtualFactory({
        topics,
        payloads: global.get('aiCpsTracePayloads'),
        payloadCatalog: global.get('aiCpsTraceCatalog'),
        traceProfile: global.get('aiCpsDefaultTraceProfile') || 'standard',
        seed: Number(env.get('FACTORY_SEED') || 42),
        baseRuntimeMs: msg._factory_base_runtime_ms,
    });
    context.set('factory', factory);
}

// Jedes von einem change-Node markierte Ereignis hat genau eine Kernmethode.
const handlers = {
    control: () => factory.handleControl(msg.payload),
    status: () => factory.handleOrchestrationStatus(msg.payload),
    tick: () => factory.tick(),
    command: () => factory.handleCommand(msg.topic),
};

// Unbekannte Ereignisse sichtbar warnen und nicht weiterleiten.
const handler = handlers[msg._factory_event];
if (!handler) { node.warn('Ignored unknown factory event: ' + msg._factory_event); return null; }

// Das Ereignis aktualisiert Commands, Einzelmodul-Laufzeiten und Jobcounter gemeinsam.
const actions = handler();

// Den aktualisierten Semaphorzustand fuer das naechste Ereignis speichern.
context.set('factory', factory);

// Ein einzelner Command oder Tick erzeugt haeufig noch keine ausgehende Aktion.
if (actions.length === 0) return null;

// Die folgenden split-/switch-Nodes verteilen MQTT- und Statusaktionen sichtbar.
msg.payload = actions;
return msg;

// Dieser Adapter baut ausschliesslich ein begrenztes Anzeigemodell auf.
// Er publiziert keine Prozessnachrichten und veraendert weder Fabrik noch KI-Flow.
const api = global.get('aiCpsHmi');
let hmi = context.get('hmi');
if (!hmi) {
    hmi = new api.HmiViewModel({ maxCycles: 30, maxErrors: 20 });
}
msg.payload = hmi.handle(msg.topic, msg.payload);
context.set('hmi', hmi);
return msg;

