/* Dashboard 2.0: Tabelleninhalt ueber alle fest reservierten Widgetzeilen spannen. */
.nrdb-ui-table > .v-table {
  grid-row: 1 / -1;
}

/* Leere optionale Felder behalten ein gut lesbares Label oberhalb des Rahmens. */
.nrdb-ui-form .v-field-label--floating {
  background: #ffffff;
  padding: 0 4px;
}
